SELECT

FROM TBL_CASHFLOW_TYPE


        AND ORG_ID = #{orgId}


        AND CASHFLOW_TYPE_CODE LIKE CONCAT('%', #{cashflowTypeCode}, '%')


        AND CASHFLOW_TYPE_NAME LIKE CONCAT('%', #{cashflowTypeName}, '%')


        AND CASHFLOW_DIRECTION = #{cashflowDirection}


        AND CASHFLOW_CATEGORY = #{cashflowCategory}


        AND IS_ENABLED = #{isEnabled}


ORDER BY SORT_ORDER ASC, CREATE_TIME DESC

SELECT

FROM TBL_CASHFLOW_TYPE
WHERE CASHFLOW_TYPE_CODE = #{cashflowTypeCode}

    AND ORG_ID = #{orgId}

